/**
 * Lazy SQL highlighter. Shiki is loaded on demand (dynamic import) so it stays out of
 * the initial bundle; the fine-grained core + JS regex engine keeps the chunk small.
 * Output is HTML generated by Shiki from escaped tokens, with colors as CSS variables
 * (--shiki-light / --shiki-dark) so both themes work without re-highlighting.
 */
type Highlighter = (code: string) => string

let highlighterPromise: Promise<Highlighter> | null = null

async function createHighlighter(): Promise<Highlighter> {
  const [{ createHighlighterCore }, { createJavaScriptRegexEngine }, sql, light, dark] =
    await Promise.all([
      import('shiki/core'),
      import('shiki/engine/javascript'),
      import('shiki/langs/sql.mjs'),
      import('shiki/themes/github-light.mjs'),
      import('shiki/themes/github-dark.mjs'),
    ])
  const core = await createHighlighterCore({
    langs: [sql.default],
    themes: [light.default, dark.default],
    engine: createJavaScriptRegexEngine(),
  })
  return (code) =>
    core.codeToHtml(code, {
      lang: 'sql',
      themes: { light: 'github-light', dark: 'github-dark' },
      defaultColor: false,
    })
}

/** Memoized: the highlighter is created once, on first use. */
export function highlightSql(code: string): Promise<string> {
  highlighterPromise ??= createHighlighter()
  return highlighterPromise.then((highlight) => highlight(code))
}
